import "./index.less"

import { getLifeActivityNodeTime, getLifeActivityRank, } from '@utils/api.js'
import { cookie } from '@utils/index.js'

var _receiveInstance = (function () {
    const globalData = {
        isSign: "",
        cr: "",
        shopId: "",
        authorization: "",

        isOpenBlank: false,
        isLifeIconImg: false,
        lifeIconImg: "",
        lifeIconText: "",
        lifeUserTabText: "",
        lifeUserTabLink: "",

        isLifeActivityIconImg: false,
        lifeActivityIconImg: "",
        lifeActivityIconText: "",
    };
    const setGlobalData = async ({ isSign, cr, shopId, authorization, isOpenBlank, isLifeIconImg, lifeIconImg, isLifeActivityIconImg, lifeActivityIconImg, lifeIconText, lifeActivityIconText, lifeUserTabText, lifeUserTabLink, }) => {
        globalData.isSign = isSign;
        globalData.cr = cr;
        globalData.shopId = shopId;
        globalData.authorization = authorization;

        globalData.isOpenBlank = isOpenBlank
        globalData.isLifeIconImg = isLifeIconImg
        globalData.lifeIconImg = lifeIconImg
        globalData.lifeIconText = lifeIconText
        globalData.lifeUserTabText = lifeUserTabText
        globalData.lifeUserTabLink = lifeUserTabLink

        globalData.isLifeActivityIconImg = isLifeActivityIconImg
        globalData.lifeActivityIconImg = lifeActivityIconImg
        globalData.lifeActivityIconText = lifeActivityIconText
    };
    const getGlobalData = () => {
        return JSON.parse(JSON.stringify(globalData));
    };
    class ReceiveJackeryLife {
        constructor(el) {
            this.init(el);
        }
        init(el) {
            setGlobalData(el);
        }
    }
    // 悬浮 icon
    class FixedIcon {
        constructor() {
          if (globalData?.isLifeActivityIconImg) {
            this.createDOM()
          }
        }
        // 创建悬浮 icon
        createDOM() {
          const oDiv = document.createElement('div')
          oDiv.id = 'life-activity-user-icon'
          oDiv.style.display = 'none'
          oDiv.className = 'flex flex-col fixed z-2000 right-16 top-[40%] lg:j-right-32 xl:a-right-32'
          oDiv.innerHTML = `
            <div class="life-user-icon relative z-2000" data-life-activity-user-icon>
              <div class="life-user-icon-tips">
                <span class="font-semibold text-#333 line-clamp-2"></span>
              </div>
            </div>
          `
    
          document.body.appendChild(oDiv)
    
          // 初始化事件
          this.init()
        }
        init() {
          this.fixedIcon = document.querySelector('[data-life-activity-user-icon]')
          if (!this.fixedIcon) return
    
          this.fixedIcon.parentElement.style.display = 'block'
    
          this.fixedIcon.style.background = `url(${globalData?.lifeActivityIconImg}) center center / contain no-repeat`
    
          const tipsDOM = this.fixedIcon.querySelector('.life-user-icon-tips')
          if (globalData?.lifeActivityIconText) {
            tipsDOM.querySelector('span').innerHTML = globalData?.lifeActivityIconText
    
            this.fixedIcon.addEventListener('mouseenter', () => tipsDOM.classList.add('active'))
            this.fixedIcon.addEventListener('mouseleave', () => tipsDOM.classList.remove('active'))
          }
    
          this.handleClick()
        }
        // 处理 click 事件
        handleClick() {
          this.fixedIcon.onclick = () => {
            // 已登录
            if (globalData?.isSign) {
              window.open(`${location.origin}/pages/life-user?curUser=true`, '_blank')
            }
            // 未登录
            else {
              window?.jackeryLoginApp.modalLogin({
                register_act: 'JL-register',
                return_url: `${window.location.origin}/pages/life-user?curUser=true`
              })
            }
          }
        }
    }
    return {
        ReceiveJackeryLife,
        FixedIcon,
        getGlobalData,
    };
})();


class BaseSwiper {
    constructor() {

    }
    $$(entity) {
        return entity ? document.querySelector(entity) : null
    }
    isMobile() {
        return document.documentElement.clientWidth < 1024
    }
    // 首字母大写
    upperFirst(str) {
        return str.charAt(0).toUpperCase() + str.slice(1)
    }
    // 补零
    padZero(number, length = 2) {
        let str = number.toString()
        while (str.length < length) {
            str = '0' + str
        }
        return str
    }
}


// 活动 Benifits
class ActivityBenefits extends BaseSwiper {
    constructor({ swiperContainerPC, swiperPaginationPC, swiperContainerMB, swiperPaginationMB, ...props }) {
        super(props)

        const swiperContainerPCDOM = document.querySelector(swiperContainerPC)
        const swiperPaginationPCDOM = document.querySelector(swiperPaginationPC)
        swiperContainerPCDOM && swiperPaginationPCDOM && this.initPC(swiperContainerPC, swiperPaginationPC)

        const swiperContainerMBDOM = document.querySelector(swiperContainerMB)
        const swiperPaginationMBDOM = document.querySelector(swiperPaginationMB)
        swiperContainerMBDOM && swiperPaginationMBDOM && this.initMB(swiperContainerMB, swiperPaginationMB)
    }
    initPC(swiperContainerPC, swiperPaginationPC) {
        // 示例
        new Swiper(swiperContainerPC, {
            centeredSlides: true,
            initialSlide: 0,
            spaceBetween: -400,
            effect: "coverflow",
            grabCursor: true,
            slidesPerView: 'auto',
            centeredSlides: true,
            loop: true,
            coverflowEffect: {
                rotate: 0,
                stretch: 0,
                depth: 200,
                modifier: 4,
                slideShadows: true,
                scale: 1,
            },
            pagination: {
                el: swiperPaginationPC,
                clickable: true,
                bulletClass: 'benefit-pagination-pc-item',
                bulletActiveClass: 'benefit-pagination-pc-item-active',
                clickableClass: 'benefit-pagination-pc-item-clickable',
                modifierClass: 'benefit-pagination-pc-',
                renderBullet: function (index, className) {
                    return `<span class="${className}"></span>`
                },
            },
            navigation: {
                nextEl: '.benefit-pc-button-next',
                prevEl: '.benefit-pc-button-prev',
            },
        });
    }
    initMB(swiperContainerMB, swiperPaginationMB) {
        new Swiper(swiperContainerMB, {
            slidesPerView: 'auto',
            spaceBetween: 0,
            loop: true,
            autoplay: false,
            pagination: {
                el: swiperPaginationMB,
                clickable: true,
                bulletClass: 'benefit-pagination-mb-item',
                bulletActiveClass: 'benefit-pagination-mb-item-active',
                clickableClass: 'benefit-pagination-mb-item-clickable',
                modifierClass: 'benefit-pagination-mb-',
                renderBullet: function (index, className) {
                    return `<span class="${className}"></span>`
                },
            },
            on: {
                resize: function () {
                    setTimeout(() => {
                        this.update()
                    }, 600);
                }
            },
        })
    }
}

